#include <algorithm>

void check_max_types() {
    int i = 10;
    long l = 20L;

    // l = std::max(i, l); // ERROR: Argument types (int, long) mismatch T

    // Correct Usage: Explicitly qualify the target type
    l = std::max<long>(i, l); // OK: Both converted to long

    double d = 3.14;
    // d = std::max<double>(d, i); // OK: i is promoted to double
}
